#!/usr/bin/env python3
"""Apply the Cabo de Gata direction/reframing to the reconstructed OOLITA site.

Generated from the reviewed canonical source changes of 22 August 2026.
Exact, idempotent replacements: unexpected source state stops the build.
"""
from pathlib import Path
import sys

ROOT = Path(sys.argv[1] if len(sys.argv) > 1 else "site")

def apply(path, old, new):
    p = ROOT / path
    if not p.is_file():
        raise SystemExit(f"Missing expected page: {path}")
    text = p.read_text(encoding="utf-8")
    if old in text:
        text = text.replace(old, new, 1)
        p.write_text(text, encoding="utf-8")
        print(f"direction patched {path}: {old[:70]!r}")
    elif new and new in text:
        print(f"direction already present {path}: {new[:70]!r}")
    elif not new and old not in text:
        print(f"direction deletion already present {path}: {old[:70]!r}")
    else:
        raise SystemExit(f"Unexpected direction state in {path}: {old[:120]!r}")

