apply('laberinto/index.html', '<p class="glosa">Un <a href="/que-es-un-laberinto/">laberinto clásico</a> de tres metros, hecho a mano en septiembre de 2021 con calcarenita suelta — piedra recogida a pocos pasos de donde ahora está — sobre una <a href="/que-es-un-oolito/">duna fósil</a> que hace cien mil años fue fondo del mar. Este laberinto tiene un solo camino: no hay bifurcaciones ni callejones sin salida, y no hay forma de perderse. Se camina despacio. Gratis, siempre abierto.</p>\n<div class="datos"><span class="rot">Trazado clásico · 3 m</span><span class="rot">Piedra suelta · 2021</span><span class="rot">Geoparque UNESCO</span></div>\n', '<p class="glosa">Un <a href="/que-es-un-laberinto/">laberinto clásico</a> de tres metros, hecho a mano en septiembre de 2021 con calcarenita suelta — piedra recogida a pocos pasos de donde ahora está — sobre una <a href="/que-es-un-oolito/">duna fósil</a> que hace cien mil años fue fondo del mar. Este laberinto tiene un solo camino: no hay bifurcaciones ni callejones sin salida, y no hay forma de perderse. Se camina despacio. Se encuentra junto al Castillo de San Felipe. No tiene personal ni entrada; recorrerlo es gratuito y conviene acercarse con cuidado y respeto por el lugar.</p>\n<div class="datos"><span class="rot">Trazado clásico · 3 m</span><span class="rot">Piedra suelta · 2021</span><span class="rot">Cabo de Gata-Níjar</span></div>\n')
